function grid$reguserinfo(f){
  this.constructor(f);
}
grid$reguserinfo.prototype = new DirEvent();
grid$reguserinfo.prototype.afterInit = function(){
	var p = this._dir;
}
grid$reguserinfo.prototype.beforeButtonGridClick = function(id){
  if (id == 'permission') {
    var p = this._dir;
    p.wait(true);

    var m = new Memvars();
    p.grequest(0, 'permission', 'GetRow', 'user_id', funResult);
    return false;
  }
  return true
}
function funResult(p, d){
  d = new DataRow(d);
  if(d.val('result') == '')
    $.createDir(false, { controller: 'permissionUser', backdropclick: false, folder: "Filter", dirViewType: "Dialog", parent: p });   
  else
    $.alert($.msg.get(d.val('result')));
}
